// Parse incoming request — from GitHub bridge, n8n-trigger, or direct
const body = $input.item.json.body || $input.item.json;

// Determine the task type
const taskType = body.action || body.task || 'compliance_check';

let chatInput = '';
if (taskType === 'pr_check' || body.pull_request) {
  const pr = body.pull_request || {};
  chatInput = `Check compliance for PR #${pr.number || body.pr_number} in ${body.repository?.full_name || body.repo || 'unknown'}. ` +
    `Branch: ${pr.head?.ref || body.branch || 'unknown'}. ` +
    `Title: ${pr.title || body.title || 'N/A'}. ` +
    (body.story_id ? `Story ID: ${body.story_id}. ` : '') +
    `Determine if this PR meets compliance requirements.`;
} else if (taskType === 'story_check') {
  chatInput = `Run compliance check for story ${body.story_id}. ` +
    `Validate that all rules are met and report any violations.`;
} else {
  chatInput = body.query || body.message || `Run compliance check: ${JSON.stringify(body)}`;
}

return {
  json: {
    chatInput,
    context: {
      task_type: taskType,
      pr_number: body.pr_number || body.pull_request?.number,
      repo: body.repository?.full_name || body.repo,
      head_sha: body.pull_request?.head?.sha || body.head_sha,
      story_id: body.story_id,
      source: body.source || 'webhook',
    }
  }
};

// Process compliance agent output and determine action
const agentOutput = $input.item.json;
const context = $('Parse Request').item.json.context;

let result;
try {
  result = typeof agentOutput.output === 'string'
    ? JSON.parse(agentOutput.output)
    : agentOutput.output;
} catch {
  result = {
    verdict: 'fail',
    summary: agentOutput.output || 'Unable to parse compliance result',
    violations: ['Parse error in agent output'],
    recommendations: ['Manual review required'],
    confidence: 0.3
  };
}

return {
  json: {
    success: true,
    agent: 'compliance',
    verdict: result.verdict || 'unknown',
    summary: result.summary,
    violations: result.violations || [],
    recommendations: result.recommendations || [],
    confidence: result.confidence || 0.5,
    context: {
      pr_number: context.pr_number,
      repo: context.repo,
      story_id: context.story_id,
      head_sha: context.head_sha,
    },
    timestamp: new Date().toISOString()
  }
};

